database_schema.zh:
PRAGMA foreign_keys = ON;

CREATE TABLE project (
  project_id TEXT PRIMARY KEY, name TEXT NOT NULL, scope_note TEXT NOT NULL,
  review_version TEXT NOT NULL, as_of_date TEXT NOT NULL
);
CREATE TABLE entity (
  entity_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL,
  standard_name TEXT NOT NULL, organism_taxid INTEGER, description TEXT,
  UNIQUE(entity_type, standard_name, organism_taxid)
);
CREATE TABLE entity_synonym (
  entity_id TEXT NOT NULL REFERENCES entity(entity_id), synonym TEXT NOT NULL,
  synonym_type TEXT, PRIMARY KEY(entity_id, synonym)
);
CREATE TABLE entity_identifier (
  entity_id TEXT NOT NULL REFERENCES entity(entity_id), namespace TEXT NOT NULL,
  identifier TEXT NOT NULL, version TEXT, url TEXT,
  PRIMARY KEY(entity_id, namespace, identifier)
);
CREATE TABLE context (
  context_id TEXT PRIMARY KEY, species_taxid INTEGER, tissue TEXT, cell_type TEXT,
  brain_region TEXT, peripheral_ganglion TEXT, disease TEXT, pain_type TEXT,
  model TEXT, sex TEXT, age TEXT, experimental_condition TEXT
);
CREATE TABLE source_document (
  source_id TEXT PRIMARY KEY, document_type TEXT NOT NULL,
  title TEXT NOT NULL, authors TEXT, journal TEXT, publication_year INTEGER,
  doi TEXT, pmid TEXT, pmcid TEXT, dataset_accession TEXT, patent_id TEXT,
  clinical_trial_id TEXT, canonical_url TEXT, open_access_status TEXT,
  metadata_verification TEXT NOT NULL, checked_at TEXT NOT NULL
);
CREATE TABLE evidence_record (
  evidence_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES source_document(source_id),
  evidence_type TEXT NOT NULL, method TEXT, assay TEXT, sample_size TEXT,
  effect_direction TEXT, result_summary TEXT NOT NULL, quote_or_locator TEXT,
  evidence_grade TEXT NOT NULL CHECK(evidence_grade IN ('A','B','C','D')),
  assertion_class TEXT NOT NULL CHECK(assertion_class IN ('established_fact','evidence_based_inference','hypothesis','counterevidence')),
  context_id TEXT REFERENCES context(context_id), curator TEXT,
  entered_at TEXT NOT NULL, database_version TEXT NOT NULL
);
CREATE TABLE claim (
  claim_id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES entity(entity_id),
  predicate TEXT NOT NULL, object_id TEXT NOT NULL REFERENCES entity(entity_id),
  direction TEXT, context_id TEXT REFERENCES context(context_id),
  assertion_class TEXT NOT NULL, claim_text TEXT NOT NULL, status TEXT NOT NULL
);
CREATE TABLE claim_evidence (
  claim_id TEXT NOT NULL REFERENCES claim(claim_id),
  evidence_id TEXT NOT NULL REFERENCES evidence_record(evidence_id),
  support_role TEXT NOT NULL CHECK(support_role IN ('supports','contradicts','qualifies')),
  PRIMARY KEY(claim_id,evidence_id)
);
CREATE TABLE interaction (
  interaction_id TEXT PRIMARY KEY, participant_a TEXT NOT NULL REFERENCES entity(entity_id),
  participant_b TEXT NOT NULL REFERENCES entity(entity_id), interaction_type TEXT NOT NULL,
  binding_site TEXT, affinity_value REAL, affinity_unit TEXT,
  context_id TEXT REFERENCES context(context_id), claim_id TEXT NOT NULL REFERENCES claim(claim_id)
);
CREATE TABLE structure_domain (
  structure_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entity(entity_id),
  pdb_id TEXT, domain_name TEXT, residues TEXT, method TEXT, resolution_angstrom REAL,
  source_id TEXT REFERENCES source_document(source_id)
);
CREATE TABLE mutation_ptm (
  modification_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entity(entity_id),
  modification_type TEXT NOT NULL, residue TEXT, functional_effect TEXT,
  evidence_id TEXT NOT NULL REFERENCES evidence_record(evidence_id)
);
CREATE TABLE assay_sample (
  assay_sample_id TEXT PRIMARY KEY, assay_type TEXT NOT NULL, readout TEXT,
  sample_type TEXT, sample_size TEXT, context_id TEXT REFERENCES context(context_id),
  evidence_id TEXT NOT NULL REFERENCES evidence_record(evidence_id)
);
CREATE TABLE intervention (
  intervention_id TEXT PRIMARY KEY, name TEXT NOT NULL, intervention_type TEXT NOT NULL,
  target_entity_id TEXT REFERENCES entity(entity_id), mechanism TEXT,
  route TEXT, safety_toxicity TEXT, development_stage TEXT,
  evidence_id TEXT REFERENCES evidence_record(evidence_id)
);
CREATE TABLE neural_circuit (
  circuit_id TEXT PRIMARY KEY, name TEXT NOT NULL, input_region TEXT,
  output_region TEXT, cell_population TEXT, phenotype TEXT,
  evidence_id TEXT REFERENCES evidence_record(evidence_id)
);
CREATE TABLE review_search (
  search_id TEXT PRIMARY KEY, project_id TEXT REFERENCES project(project_id),
  database_name TEXT NOT NULL, query_text TEXT NOT NULL, date_start TEXT,
  date_end TEXT, executed_at TEXT NOT NULL, hit_count INTEGER,
  export_path TEXT, notes TEXT
);
CREATE TABLE screening_record (
  screening_id TEXT PRIMARY KEY, search_id TEXT REFERENCES review_search(search_id),
  source_id TEXT REFERENCES source_document(source_id), stage TEXT NOT NULL,
  decision TEXT NOT NULL, exclusion_reason TEXT, reviewer TEXT, decided_at TEXT
);
CREATE TABLE candidate (
  candidate_id TEXT PRIMARY KEY, pain_group TEXT NOT NULL, target_name TEXT NOT NULL UNIQUE,
  gene_symbol TEXT NOT NULL, mechanism_axis TEXT NOT NULL, development_status TEXT,
  evidence_gap TEXT, falsification_test TEXT
);
CREATE TABLE candidate_score (
  candidate_id TEXT PRIMARY KEY REFERENCES candidate(candidate_id),
  mechanism_evidence REAL NOT NULL, novelty_sparsity REAL NOT NULL,
  tractability REAL NOT NULL, human_relevance REAL NOT NULL,
  cell_circuit_specificity REAL NOT NULL, safety_window REAL NOT NULL,
  weighted_score REAL NOT NULL, scored_at TEXT NOT NULL, rubric_version TEXT NOT NULL
);

CREATE VIEW traceable_graph_edges AS
SELECT c.claim_id, s.standard_name AS subject, c.predicate, o.standard_name AS object,
       c.assertion_class, e.evidence_id, ce.support_role, d.doi, d.pmid, d.canonical_url
FROM claim c JOIN entity s ON s.entity_id=c.subject_id
JOIN entity o ON o.entity_id=c.object_id
JOIN claim_evidence ce ON ce.claim_id=c.claim_id
JOIN evidence_record e ON e.evidence_id=ce.evidence_id
JOIN source_document d ON d.source_id=e.source_id;

CREATE TRIGGER claim_requires_valid_entities BEFORE INSERT ON claim
BEGIN
  SELECT CASE WHEN NEW.subject_id=NEW.object_id AND NEW.predicate NOT IN ('self_associates','same_as')
    THEN RAISE(ABORT,'self-edge requires an explicit self predicate') END;
END;

